package org.joda.time.base;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.time.Chronology;
import org.joda.time.DateTimeUtils;
import org.joda.time.DurationField;
import org.joda.time.DurationFieldType;
import org.joda.time.MutablePeriod;
import org.joda.time.Period;
import org.joda.time.PeriodType;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.ReadablePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BaseSingleFieldPeriod#equals
 */
public class BaseSingleFieldPeriod_equals_TriageGen0Test {

    /**
     * Concrete implementation of BaseSingleFieldPeriod for testing purposes
     * since the constructor is protected and the class is abstract.
     */
    private static class TestPeriod extends BaseSingleFieldPeriod {
        private final PeriodType periodType;
        private final DurationFieldType fieldType;

        protected TestPeriod(int value, PeriodType periodType, DurationFieldType fieldType) {
            super(value);
            this.periodType = periodType;
            this.fieldType = fieldType;
        }

        @Override
        public PeriodType getPeriodType() {
            return periodType;
        }

        @Override
        public DurationFieldType getFieldType() {
            return fieldType;
        }

        @Override
        public DurationFieldType getFieldType(int index) {
            return fieldType;
        }

        @Override
        public int size() {
            return 1;
        }

        @Override
        public boolean isSupported(DurationFieldType type) {
            return type.equals(fieldType);
        }

        @Override
        public int get(DurationFieldType type) {
            return getValue();
        }

        @Override
        public int getValue(int index) {
            return getValue();
        }

        @Override
        public Period toPeriod() {
            return null; // Not needed for equals test
        }

        @Override
        public org.joda.time.MutablePeriod toMutablePeriod() {
            return null; // Not needed for equals test
        }
    }

    @Test
    public void testEquals_SameInstance() {
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        // Covers: if (this == period) return true;
        assertTrue(period.equals(period));
    }

    @Test
    public void testEquals_NullObject() {
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        // Covers: if (period instanceof ReadablePeriod == false) return false;
        assertFalse(period.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        String notAPeriod = "not a period";
        // Covers: if (period instanceof ReadablePeriod == false) return false;
        assertFalse(period.equals(notAPeriod));
    }

    @Test
    public void testEquals_SameValues() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        TestPeriod period2 = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        // Covers: return (other.getPeriodType() == getPeriodType() && other.getValue(0) == getValue());
        assertTrue(period1.equals(period2));
    }

    @Test
    public void testEquals_DifferentPeriodType() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        // Using a different PeriodType (assuming PeriodType has multiple implementations or mocking)
        // Since PeriodType is often a singleton/enum-like, we use a mock if needed, 
        // but here we rely on the logic of the comparison.
        PeriodType differentType = Mockito.mock(PeriodType.class);
        TestPeriod period2 = new TestPeriod(10, differentType, DurationFieldType.days());

        // Covers: other.getPeriodType() == getPeriodType() is false
        assertFalse(period1.equals(period2));
    }

    @Test
    public void testEquals_DifferentValue() {
        TestPeriod period1 = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());
        TestPeriod period2 = new TestPeriod(20, PeriodType.standard(), DurationFieldType.days());
        // Covers: other.getValue(0) == getValue() is false
        assertFalse(period1.equals(period2));
    }

    @Test
    public void testEquals_WithMockReadablePeriod() {
        // This tests the branch where it is a ReadablePeriod but logic fails
        TestPeriod period = new TestPeriod(10, PeriodType.standard(), DurationFieldType.days());

        org.joda.time.ReadablePeriod mockPeriod = Mockito.mock(org.joda.time.ReadablePeriod.class);
        when(mockPeriod.getPeriodType()).thenReturn(PeriodType.standard());
        when(mockPeriod.getValue(0)).thenReturn(99); // Different value

        // Covers: period instanceof ReadablePeriod == true, but equality check fails
        assertFalse(period.equals(mockPeriod));

        when(mockPeriod.getPeriodType()).thenReturn(Mockito.mock(PeriodType.class)); // Different type
        assertFalse(period.equals(mockPeriod));
    }
}
